use std::collections::HashMap;

fn two_sum(nums: &Vec<i32>, target: i32) -> Vec<usize> {
    // Map from number to its index
    let mut map = HashMap::new();

    for (i, &num) in nums.iter().enumerate() {
        let complement = target - num;
        // Check if complement already seen
        if let Some(&idx) = map.get(&complement) {
            // Return indices in increasing order
            if idx < i {
                return vec![idx, i];
            } else {
                return vec![i, idx];
            }
        }
        // Insert current number and index into the map
        map.insert(num, i);
    }

    // According to problem statement, this case won't happen because
    // there is always exactly one solution.
    unreachable!("No two sum solution found");
}